    },
    {
      "card_ids": ["C05"],
      "claim": "A close 1-benzylpiperidine spiro compound showed ~4% ID/g brain uptake at 5 min in mice, indicating favorable brain penetration.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C02"],
      "claim": "A 1-benzylpiperidine benzamide accumulated significantly in monkey brain, demonstrating cross-species CNS penetration for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "A lipophilic dimethoxy benzamide with a benzyl ether reached a free brain/plasma ratio of ~0.5 in mice, supporting that the query's lipophilic dimethoxy/benzyl features are compatible with BBB passage.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
